-- challenge chal_coding_nae_122 (mini_coding)
INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_coding_nae_122', (SELECT id FROM catalog.course WHERE public_id = 'nodejs-ai-engineering'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'nodejs-ai-engineering') AND order_index = 1 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-nae-1-2' AND is_deleted = false LIMIT 1), 'render-versioned-prompt', 'Render a versioned prompt template', 'The CodeDev hint service builds its prompt from the template hint-v3 (version 3). The old renderer, `text.replace(/\{\{(\w+)\}\}/g, (_, k) => String(vars[k]))`, put the word "undefined" into the prompt when a variable was renamed, logged no version, and treated `{{...}}` inside learner code as template syntax. Write renderPrompt(template, variables) for template = { id, version, text } and variables = an object of values parsed from JSON. Return { ok: true, ref, prompt, warnings } or { ok: false, ref, errors, warnings }. Rules: (1) ref is "<id>@<version>", for example "hint-v3@3", on every result. (2) Read text once, from left to right. A backslash followed by {{ (the three characters \{{) is an escape: write a literal {{ and continue after it. {{ followed by a name and }} is a placeholder; a name is a letter (A-Z, a-z) followed by letters, digits or underscores, with no spaces. Any other {{ is an error "malformed placeholder at <index>", where index is the 0-based position of that {{ in text; continue scanning right after those two braces. All other characters (a single {, a }} on its own, a backslash not followed by {{) are copied as they are. (3) A placeholder whose variable is a string is replaced by that string; a number is replaced by String(value). Anything else (no such key, null, true or false, an object, an array) is an error "missing variable: <name>", reported once per name, at its first occurrence. An empty string and 0 are values. (4) Insert values exactly as given and never scan them again: {{...}}, \{{ and $& inside a value stay as they are. (5) errors are in the order the scan finds them. If there is at least one error, return ok: false with all of them and no prompt. (6) warnings: "unused variable: <name>" for every key of variables that no placeholder in the template uses (a malformed placeholder uses nothing), sorted by name (the default string sort), on both kinds of result. The runner reads a list of { template, variables } and prints the list of results as JSON.', 'open', 'easy'::difficulty_question, 'mini_coding', 20, true, false)
