INSERT INTO challenge.challenge_hints (challenge_id, level, body)
VALUES ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_nae_122'), 1, 'If you replace the placeholders one variable at a time, what happens when the learner''s code itself contains "{{challengeTitle}}"? What would a renderer have to do so that a value is never looked at a second time?'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_nae_122'), 2, 'Walk through text with an index and build the output in a separate string. At each position there are only three cases to check, in this order: does the text start with \{{ here, does it start with {{ here, or is it a plain character? For the {{ case, a regular expression with the sticky flag (/.../y) and lastIndex = i tests a name and the closing braces at exactly that position. Keep a Set of used names (for the warnings) and a Set of names already reported as missing.'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_nae_122'), 3, 'A similar scan on a different syntax, ${name} with $${ as the escape, for the text "Hi ${user}, cost $${x} ${user}" and variables { user: "Ann", unused: 1 }: at index 3 the text starts with ${ and the name user is followed by } -> append "Ann", add user to used, jump past the closing brace. At index 15 the text starts with $${ -> append "${" and jump 3 characters. The rest is copied. Result: "Hi Ann, cost ${x} Ann", warnings ["unused variable: unused"]. If user had been null, the result would instead be one error, "missing variable: user", even though user appears twice.');
