VALUES ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_nae_122'), 'hint-v3 rendered with every variable; an extra userEmail variable is only a warning', '[{"template":{"id":"hint-v3","version":3,"text":"You are a patient programming tutor on CodeDev.\nWrite hint level {{hintLevel}} of 3 for the challenge \"{{challengeTitle}}\" ({{language}}).\nDo not write the full solution.\n\nLearner code:\n<code>\n{{learnerCode}}\n</code>\n\nTest output:\n{{testOutput}}\n\nAnswer only with JSON."},"variables":{"hintLevel":1,"challengeTitle":"Sum of an array","language":"typescript","learnerCode":"function sum(xs: number[]): number {\n  let total = 0;\n  for (let i = 1; i < xs.length; i++) total += xs[i];\n  return total;\n}","testOutput":"expected 6, got 5"}},{"template":{"id":"hint-v3","version":3,"text":"You are a patient programming tutor on CodeDev.\nWrite hint level {{hintLevel}} of 3 for the challenge \"{{challengeTitle}}\" ({{language}}).\nDo not write the full solution.\n\nLearner code:\n<code>\n{{learnerCode}}\n</code>\n\nTest output:\n{{testOutput}}\n\nAnswer only with JSON."},"variables":{"hintLevel":2,"challengeTitle":"Sum of an array","language":"typescript","learnerCode":"function sum(xs: number[]): number {\n  let total = 0;\n  for (let i = 1; i < xs.length; i++) total += xs[i];\n  return total;\n}","testOutput":"expected 6, got 5","userEmail":"lan.nguyen@example.com","attempt":4}}]', '[{"ok":true,"ref":"hint-v3@3","prompt":"You are a patient programming tutor on CodeDev.\nWrite hint level 1 of 3 for the challenge \"Sum of an array\" (typescript).\nDo not write the full solution.\n\nLearner code:\n<code>\nfunction sum(xs: number[]): number {\n  let total = 0;\n  for (let i = 1; i < xs.length; i++) total += xs[i];\n  return total;\n}\n</code>\n\nTest output:\nexpected 6, got 5\n\nAnswer only with JSON.","warnings":[]},{"ok":true,"ref":"hint-v3@3","prompt":"You are a patient programming tutor on CodeDev.\nWrite hint level 2 of 3 for the challenge \"Sum of an array\" (typescript).\nDo not write the full solution.\n\nLearner code:\n<code>\nfunction sum(xs: number[]): number {\n  let total = 0;\n  for (let i = 1; i < xs.length; i++) total += xs[i];\n  return total;\n}\n</code>\n\nTest output:\nexpected 6, got 5\n\nAnswer only with JSON.","warnings":["unused variable: attempt","unused variable: userEmail"]}]', 3, true, false, 1),
