-- challenge chal_quiz_nae_131 (quiz)
INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_quiz_nae_131', (SELECT id FROM catalog.course WHERE public_id = 'nodejs-ai-engineering'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'nodejs-ai-engineering') AND order_index = 1 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-nae-1-3' AND is_deleted = false LIMIT 1), 'structured-output-quiz', 'Structured output: validate before you use it', 'Two recorded answers of the hint model: one that type-checks but is not what the type says, and one cut short with structured output turned on.', 'open', 'medium'::difficulty_question, 'quiz', 10, true, false)
ON CONFLICT (public_id) DO UPDATE SET
    course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, lesson_id = EXCLUDED.lesson_id, name = EXCLUDED.name,
    title = EXCLUDED.title, description = EXCLUDED.description, difficulty = EXCLUDED.difficulty, type = EXCLUDED.type,
    points = EXCLUDED.points, is_published = true, is_deleted = false, updated_at = now();
DELETE FROM challenge.challenge_hints WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_nae_131');
UPDATE challenge.challenges SET quiz_display_count = NULL WHERE id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_nae_131');
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_nae_131'), 'hints/hint.service.ts:

type HintAnswer = { hint: string; level: 1 | 2 | 3; references: string[]; revealsSolution: boolean };

const answer: HintAnswer = JSON.parse(result.text);
return answer;   // sent to the lesson page

result.text, recorded by the gateway:
{"hint":"Check where your loop starts.","level":"2","references":["Arrays, lesson 3"],"revealsSolution":false}

$ npx tsc --noEmit
(no output, exit code 0)

Statement: "Because tsc reports no errors and HintAnswer declares level as 1 | 2 | 3, the lesson page receives level as a number."', 'single_choice'::question_type, 'False. JSON.parse returns any, and any can be assigned to HintAnswer without a single check, so the compiler has nothing to complain about. Types are erased at runtime: the object that reaches the page is exactly what the model wrote, with level as the string "2". On the page, level === 2 is false, a switch over level falls through to its default branch, and "2" + 1 is "21". The type annotation is a claim about the value, not a check of it; only code that looks at the value at runtime (a validator, a schema library) turns the claim into a fact. The misconception is that a clean tsc run covers data that arrives at runtime: from the network, from the database or from a model.', 1, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_nae_131') AND order_index = 1)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
SELECT q.id, o.option_text, o.is_correct
FROM q, (VALUES
        ('True', false),
        ('False', true)
    ) AS o(option_text, is_correct);
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_nae_131'), 'The hint service asks the gateway for JSON that follows the schema; the provider''s structured output feature is turned on for this request:

gateway.complete({ promptRef: "hint-v3@3", output: { format: "json", schema: hintAnswerSchema }, maxOutputTokens: 120 })

Gateway log line:
{"event":"llm.call","promptRef":"hint-v3@3","model":"model-small","stopReason":"max_tokens","outputTokens":120,"latencyMs":2210}

result.text:
{"hint":"Your loop starts at index 1, so the first element is never added. Look at the initial value of i and compare it with the first index of an ar

Statement: "Even with structured output turned on, this response must go through the server''s validator, and the validator should reject it before the lesson page sees it."', 'single_choice'::question_type, 'True. The log says the model stopped because it reached the output token limit (stopReason max_tokens), so the JSON was cut in the middle of a string and will not even parse. Structured output features make a valid answer much more likely, but a response can still be truncated, a fallback model may not support the feature, a refusal can come back in another shape, and which schema keywords a provider enforces differs between providers (check the provider''s current docs). The validator is the only place that knows for sure, so the server checks every answer and turns a broken one into a typed error (retry or fallback is the next module) instead of a crash on the page. The misconception is that asking for a schema is the same as getting one.', 2, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_nae_131') AND order_index = 2)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
SELECT q.id, o.option_text, o.is_correct
FROM q, (VALUES
        ('True', true),
        ('False', false)
    ) AS o(option_text, is_correct);

-- challenge chal_coding_nae_132 (mini_coding)
INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_coding_nae_132', (SELECT id FROM catalog.course WHERE public_id = 'nodejs-ai-engineering'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'nodejs-ai-engineering') AND order_index = 1 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-nae-1-3' AND is_deleted = false LIMIT 1), 'validate-hint-json', 'Validate the hint model''s JSON output', 'The hint model is asked to answer with JSON for { hint, level, references, revealsSolution }. The old service did `JSON.parse(text.match(/\{[\s\S]*\}/)![0]) as HintAnswer`; one answer came wrapped in prose with "level": "2", the cast let it through and the lesson page crashed. Write parseHintAnswer(text) that returns { ok: true, value } with a HintAnswer, or { ok: false, errors } with every problem found. Rules, in this order: (1) Trim text. If the whole trimmed text is one fence, take only its content: the first line is ``` or ```json (json in any case, spaces or tabs allowed after it), the last line is ```, and lines may end with \n or \r\n. Anything before or after the fence means the text is not a fence. Do not search for JSON inside prose. (2) If JSON.parse fails, the only error is "$: not valid JSON". (3) If the value is not a plain object (null, an array, a string, a number), the only error is "$: expected an object". (4) Otherwise collect errors: first "$.<key>: unexpected key" for each key that is not one of the four, in the order of the object''s keys; then the four fields in this order. hint: "$.hint: required" when the key is absent, "$.hint: expected a string", "$.hint: must not be blank" (empty or only whitespace), "$.hint: longer than 400 characters" (string length; exactly 400 is allowed). level: "$.level: required" or "$.level: expected 1, 2 or 3" (only the numbers 1, 2 and 3; the string "2" is an error). references: "$.references: required", "$.references: expected an array", or, for an array, "$.references: more than 3 items" when it has more than 3, then "$.references[<i>]: expected a string" for every item that is not a string. revealsSolution: "$.revealsSolution: required" or "$.revealsSolution: expected a boolean". A key that is present with the value null is not absent: it gets the type error. Each field gets at most one error, except the items of references. (5) With no errors, value is a new object with exactly the four fields. revealsSolution: true is valid here: deciding what to do with it is the service''s job, not the validator''s. No libraries, and no `as HintAnswer`. The runner reads a list of raw outputs and prints the list of results as JSON.', 'open', 'easy'::difficulty_question, 'mini_coding', 20, true, false)
ON CONFLICT (public_id) DO UPDATE SET
    course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, lesson_id = EXCLUDED.lesson_id, name = EXCLUDED.name,
    title = EXCLUDED.title, description = EXCLUDED.description, difficulty = EXCLUDED.difficulty, type = EXCLUDED.type,
    points = EXCLUDED.points, is_published = true, is_deleted = false, updated_at = now();
