INSERT INTO challenge.challenge_hints (challenge_id, level, body)
VALUES ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_nae_132'), 1, 'Which questions have to be answered before you can look at a single field: is there a fence around the whole text, is it JSON at all, is it an object? And once you reach the fields, should the first problem end the check, or should you keep going so the log shows everything that was wrong?'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_nae_132'), 2, 'Look at four tools: a regular expression anchored at both ends (^ at the start and $ at the end, with a capture group for the content) for the fence; try/catch around JSON.parse with the result typed as unknown; a type guard isRecord(v) that rules out null and arrays; and Object.prototype.hasOwnProperty.call(obj, key) to tell an absent key from a key whose value is null. Object.keys(obj) gives the keys in their order for the unexpected-key check.'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_nae_132'), 3, 'The same steps on a different schema, { severity: "info" | "warning"; line: integer >= 1 }, for the input {"severity":"error","line":"12","author":"bot"}: the keys are severity, line, author, so the first error is "$.author: unexpected key"; severity is present but not allowed -> "$.severity: expected info or warning"; line is a string -> "$.line: expected an integer >= 1". Three errors, returned together. For {"severity":"info"} the only error is "$.line: required". For [1, 2] the only error is "$: expected an object", and the fields are never looked at.');
