VALUES ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_nae_132'), 'A valid answer as plain JSON, in a ```json fence and in a bare ``` fence', '["{\"hint\":\"Your loop starts at index 1. Which index does the first element of an array have?\",\"level\":1,\"references\":[\"Arrays, lesson 3\"],\"revealsSolution\":false}","```json\n{\n  \"hint\": \"Your loop starts at index 1. Which index does the first element of an array have?\",\n  \"level\": 2,\n  \"references\": [],\n  \"revealsSolution\": false\n}\n```","```\n{\"hint\":\"Your loop starts at index 1. Which index does the first element of an array have?\",\"level\":3,\"references\":[\"Loops\",\"Arrays, lesson 3\",\"Off-by-one errors\"],\"revealsSolution\":true}\n```\n"]', '[{"ok":true,"value":{"hint":"Your loop starts at index 1. Which index does the first element of an array have?","level":1,"references":["Arrays, lesson 3"],"revealsSolution":false}},{"ok":true,"value":{"hint":"Your loop starts at index 1. Which index does the first element of an array have?","level":2,"references":[],"revealsSolution":false}},{"ok":true,"value":{"hint":"Your loop starts at index 1. Which index does the first element of an array have?","level":3,"references":["Loops","Arrays, lesson 3","Off-by-one errors"],"revealsSolution":true}}]', 3, true, false, 1),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_nae_132'), 'The incident: JSON wrapped in prose, and level "2" with references as a string', '["Sure! Here is a hint for you:\n```json\n{\"hint\":\"Check where your loop starts.\",\"level\":\"2\",\"references\":\"Arrays, lesson 3\",\"revealsSolution\":false}\n```\nGood luck!","{\"hint\":\"Check where your loop starts.\",\"level\":\"2\",\"references\":\"Arrays, lesson 3\",\"revealsSolution\":false}"]', '[{"ok":false,"errors":["$: not valid JSON"]},{"ok":false,"errors":["$.level: expected 1, 2 or 3","$.references: expected an array"]}]', 3, true, false, 2),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_nae_132'), 'Fences: JSON tag in capitals, CRLF, spaces around; code fences inside the hint string', '["  \n```JSON  \r\n{\"hint\":\"Your loop starts at index 1. Which index does the first element of an array have?\",\"level\":1,\"references\":[\"Arrays, lesson 3\"],\"revealsSolution\":false}\r\n```  \n","{\"hint\":\"Compare with this loop:\\n```ts\\nfor (let i = 0; i < n; i++) {}\\n```\\nWhat is different?\",\"level\":1,\"references\":[\"Arrays, lesson 3\"],\"revealsSolution\":false}","```json\n{\"hint\":\"Compare with:\\n```ts\\nfor (let i = 0; ...)\\n```\",\"level\":1,\"references\":[\"Arrays, lesson 3\"],\"revealsSolution\":false}\n```","```json\n{\"hint\":\"Your loop starts at index 1. Which index does the first element of an array have?\",\"level\":1,\"references\":[\"Arrays, lesson 3\"],\"revealsSolution\":false}\n```\nHope this helps!","```json {\"hint\":\"Your loop starts at index 1. Which index does the first element of an array have?\",\"level\":1,\"references\":[\"Arrays, lesson 3\"],\"revealsSolution\":false} ```"]', '[{"ok":true,"value":{"hint":"Your loop starts at index 1. Which index does the first element of an array have?","level":1,"references":["Arrays, lesson 3"],"revealsSolution":false}},{"ok":true,"value":{"hint":"Compare with this loop:\n```ts\nfor (let i = 0; i < n; i++) {}\n```\nWhat is different?","level":1,"references":["Arrays, lesson 3"],"revealsSolution":false}},{"ok":true,"value":{"hint":"Compare with:\n```ts\nfor (let i = 0; ...)\n```","level":1,"references":["Arrays, lesson 3"],"revealsSolution":false}},{"ok":false,"errors":["$: not valid JSON"]},{"ok":false,"errors":["$: not valid JSON"]}]', 3, false, true, 3),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_nae_132'), 'Unexpected keys in input order, then required keys; an empty object lists all four', '["{\"solution\":\"for (let i = 0; i < xs.length; i++) total += xs[i];\",\"hint\":\"Your loop starts at index 1. Which index does the first element of an array have?\",\"level\":1,\"references\":[\"Arrays, lesson 3\"],\"revealsSolution\":false,\"confidence\":0.92}","{\"hint\":\"Check the loop.\"}","{}"]', '[{"ok":false,"errors":["$.solution: unexpected key","$.confidence: unexpected key"]},{"ok":false,"errors":["$.level: required","$.references: required","$.revealsSolution: required"]},{"ok":false,"errors":["$.hint: required","$.level: required","$.references: required","$.revealsSolution: required"]}]', 3, false, true, 4),
