-- challenge chal_coding_nae_232 (fix_bug)
INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_coding_nae_232', (SELECT id FROM catalog.course WHERE public_id = 'nodejs-ai-engineering'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'nodejs-ai-engineering') AND order_index = 2 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-nae-2-3' AND is_deleted = false LIMIT 1), 'the-bill-exploded', 'The Bill Exploded', 'Since release 2026.10.23-1 the provider dashboard of the CodeDev AI hint shows about 40 times more input tokens a day while learners click Hint as often as before. The hint service log shows one hint request sent to the model again and again while the answer is not valid JSON, and the prompt log shows about 120k input tokens per call because the whole repository of the learner''s submission is in the context.

Fix hintFor and buildContext so that one hint request:
- sends a context with only the failing test''s file first, then the files that test file imports, in the order of its imports list; imports that are not files of the repository (packages such as "vitest") and repeated imports are ignored; a file is added only if the tokens of the files added so far plus its own stay within budgetTokens, otherwise it is skipped and the next one is tried;
- after an invalid answer sends a repair request (repairMessages with that answer and the errors of validateHint), at most MAX_REPAIRS (2) of them, then returns FALLBACK_HINT with source "fallback"; source is "model" for a valid first answer and "repair" for a valid answer to a repair request.

The tests use a fake model (no real LLM is called) that replays scripted answers, repeats the last one when the script runs out and refuses calls after the 50th, like a spending cap. Token counts of the files are given in the input. Each test prints the context, the calls made, the tokens sent and the final result. Input: { budgetTokens, failure: { testFile, testName, output }, files: [{ path, tokens, imports }], script }.', 'open', 'medium'::difficulty_question, 'fix_bug', 30, true, false)
