-- challenge chal_quiz_nae_311 (quiz)
INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_quiz_nae_311', (SELECT id FROM catalog.course WHERE public_id = 'nodejs-ai-engineering'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'nodejs-ai-engineering') AND order_index = 3 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-nae-3-1' AND is_deleted = false LIMIT 1), 'tool-calling-who-decides', 'Tool calling: who decides what runs?', 'Two pieces of evidence from the AI tutor: the trace of the getSubmission incident with the fix that followed, and a handler that trusts the JSON Schema it sent to the model.', 'open', 'medium'::difficulty_question, 'quiz', 10, true, false)
ON CONFLICT (public_id) DO UPDATE SET
