FROM q, (VALUES
        ('True', true),
        ('False', false)
    ) AS o(option_text, is_correct);
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_nae_311'), 'Tool definition the server sends with every tutor request:
{
  "name": "listMySubmissions",
  "parameters": {
    "type": "object",
    "properties": {
      "courseId": { "type": "string" },
      "limit": { "type": "integer", "minimum": 1, "maximum": 20 }
    },
    "required": ["courseId"],
    "additionalProperties": false
  }
}

Handler:
const args = JSON.parse(call.arguments) as { courseId: string; limit?: number };
const rows = await listSubmissions(session.userId, args.courseId, args.limit ?? 10);

Statement: "Because the schema marks courseId as required, keeps limit between 1 and 20 and forbids extra properties, the parsed arguments always match it, so the cast is safe without further checks."', 'single_choice'::question_type, 'False. The schema is sent to the model as part of the request: it guides what the model writes, and whether a provider enforces it depends on the provider, the model and the mode you asked for (some offer a strict or constrained mode; check the current documentation). The gateway may also fall back to another provider, and fakes and recorded fixtures contain whatever they contain. At runtime the cast checks nothing: {"courseId":"sql-basics","limit":"5"}, a limit of 500, a missing courseId or truncated JSON all reach listSubmissions. Parse the text as unknown and validate it against the same rules on the server. The misconception is that describing a shape to the model is the same as validating it.', 2, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_nae_311') AND order_index = 2)
    RETURNING id
)
