-- challenge chal_coding_nae_312 (mini_coding)
INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_coding_nae_312', (SELECT id FROM catalog.course WHERE public_id = 'nodejs-ai-engineering'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'nodejs-ai-engineering') AND order_index = 3 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-nae-3-1' AND is_deleted = false LIMIT 1), 'tool-call-gate', 'The tool gate: check every proposed call before it runs', 'The CodeDev AI tutor lets the model propose tool calls; this gate decides which ones run. Incident: getSubmission took a userId argument from the model, and a pasted prompt made the tutor read learner u_2291''s code for learner u_1047. Write checkToolCalls(input). Input: { sessionUserId, confirmedCallIds, tools, calls }. A tool is { name, permission: "read-only" | "needs-confirmation", scope: "user" | "public", parameters }, where parameters maps each argument name to { type: "string" | "integer" | "boolean", required, minimum?, maximum?, maxLength?, enum? }. A proposed call is { id, name, arguments }, where arguments is the raw JSON text the model produced. Return one decision per call, in the same order: { id, tool, status: "run", args } or { id, tool, status: "rejected", reason }, where tool is the proposed name. Check in this order; the first failure gives the reason: (1) no tool has exactly that name: unknown tool "<name>". (2) JSON.parse throws: arguments are not valid JSON. (3) the value is not a plain object (null, an array, a string or a number): arguments must be a JSON object. (4) it has an own property userId, with any value, even the session''s: userId comes from the session. (5) the first of its own keys, in key order, that is not an own key of parameters: unexpected argument "<key>" (inherited names such as constructor or toString are not parameters). (6) each parameter, in the order of parameters: absent and required gives missing argument "<p>" (absent and optional is skipped; null counts as present with a wrong type); an integer must be a number for which Number.isInteger is true, else argument "<p>" must be integer, and below minimum or above maximum gives argument "<p>" is out of range; a string must be a string, else argument "<p>" must be string, then longer than maxLength gives argument "<p>" is too long, then a value not in enum (exact, case-sensitive) gives argument "<p>" is not an allowed value; a boolean must be true or false, else argument "<p>" must be boolean. (7) a needs-confirmation tool whose call id is not in confirmedCallIds: needs confirmation. Otherwise the call runs with args = a new object holding only the declared parameters that were given, plus userId = sessionUserId when the tool''s scope is "user" (key order inside args does not matter). The runner reads one input and prints the list of decisions as JSON.', 'open', 'medium'::difficulty_question, 'mini_coding', 30, true, false)
ON CONFLICT (public_id) DO UPDATE SET
    course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, lesson_id = EXCLUDED.lesson_id, name = EXCLUDED.name,
    title = EXCLUDED.title, description = EXCLUDED.description, difficulty = EXCLUDED.difficulty, type = EXCLUDED.type,
    points = EXCLUDED.points, is_published = true, is_deleted = false, updated_at = now();
