VALUES ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_nae_312'), 1, 'For a single proposed call, which question has to be answered before any other question even makes sense? Write the checks as a list in that order, and let the first failing one produce the reason.'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_nae_312'), 2, 'Look at four places: a Map from tool name to definition; JSON.parse inside try/catch with the result typed unknown; a plain-object check (typeof, null, Array.isArray) before you read any key; and Object.hasOwn(obj, key), both for "did the model send userId" and for "is this key a declared parameter" - the in operator also finds inherited names such as constructor. Build args as a fresh object while you check each parameter, and add userId last.'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_nae_312'), 3, 'A similar gate on different data: a scheduleReminder tool (needs-confirmation, scope user) with minutes (integer, required, 5 to 120) and note (string, optional, maxLength 20). Trace: ''{"minutes":"30"}'' -> argument "minutes" must be integer. ''{"minutes":30,"channel":"sms"}'' -> unexpected argument "channel" (found before any parameter is checked). ''{"minutes":3}'' -> argument "minutes" is out of range. ''{"minutes":30}'' not confirmed -> needs confirmation; confirmed -> run with { minutes: 30, userId: <the session''s id> }.');
INSERT INTO challenge.coding_configs (challenge_id, execution_mode, time_limit_ms, memory_limit_mb, max_attempts, scoring_mode)
VALUES ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_nae_312'), 'stdio', 3000, 128, NULL, 'all_or_nothing')
ON CONFLICT (challenge_id) DO UPDATE SET
    execution_mode = EXCLUDED.execution_mode, time_limit_ms = EXCLUDED.time_limit_ms, memory_limit_mb = EXCLUDED.memory_limit_mb,
    max_attempts = EXCLUDED.max_attempts, scoring_mode = EXCLUDED.scoring_mode, updated_at = now();
