-- challenge chal_quiz_nae_321 (quiz)
INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_quiz_nae_321', (SELECT id FROM catalog.course WHERE public_id = 'nodejs-ai-engineering'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'nodejs-ai-engineering') AND order_index = 3 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-nae-3-2' AND is_deleted = false LIMIT 1), 'streaming-broken-stream', 'Is this stream finished?', 'Two pieces of evidence from the tutor''s streaming incident: a hint request that the edge proxy closed half-way, and two network chunks that split a Vietnamese letter.', 'open', 'medium'::difficulty_question, 'quiz', 10, true, false)
ON CONFLICT (public_id) DO UPDATE SET
    course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, lesson_id = EXCLUDED.lesson_id, name = EXCLUDED.name,
    title = EXCLUDED.title, description = EXCLUDED.description, difficulty = EXCLUDED.difficulty, type = EXCLUDED.type,
    points = EXCLUDED.points, is_published = true, is_deleted = false, updated_at = now();
DELETE FROM challenge.challenge_hints WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_nae_321');
UPDATE challenge.challenges SET quiz_display_count = NULL WHERE id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_nae_321');
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_nae_321'), 'Raw stream, captured with curl -N:
data: {"delta":"To fix the off-by-one, "}

data: {"delta":"change the loop condition to"}

curl: (18) transfer closed with outstanding read data remaining

Edge proxy log for the same request:
POST /api/tutor/hint 200 bytes_sent=412 duration=30001ms termination=idle_timeout

Browser code after the read loop:
while (true) {
  const { value, done } = await reader.read();
  if (done) break;
  // ... append deltas ...
}
await saveHint({ challengeId, text, status: "done" });

Statement: "The response status was 200 and reader.read() finished with done: true without throwing, so this answer can be saved as a finished hint."', 'single_choice'::question_type, 'False. In a streamed response the status line and headers are sent before the first byte of the body, so 200 only says the stream started. The proxy log shows the connection was closed by an idle timeout after 30 s, and the reader reports that as an ordinary end of the body: done is true and nothing is thrown. The only proof that the answer is complete is the gateway''s final [DONE] event, which never arrived. This answer is truncated: show it as interrupted, offer a retry, and never save or cache it as done. The misconception is to read "the stream ended without an exception" as "the stream finished".', 1, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_nae_321') AND order_index = 1)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
SELECT q.id, o.option_text, o.is_correct
FROM q, (VALUES
        ('True', false),
        ('False', true)
    ) AS o(option_text, is_correct);
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_nae_321'), 'Two network chunks of one tutor stream, as bytes (the letter ợ is e1 bb a3 in UTF-8):
chunk 1: 64 61 74 61 3a 20 7b 22 64 65 6c 74 61 22 3a 22 47 e1 bb   -> data: {"delta":"G + the first two bytes of ợ
chunk 2: a3 69 20 c3 bd 22 7d 0a 0a                                  -> the last byte of ợ, then i ý"}\n\n

Client code, run for each chunk:
const text = new TextDecoder().decode(chunk);
for (const event of text.split("\n\n")) { /* JSON.parse the data line */ }

Statement: "Two separate problems hit this event: the split letter turns into replacement characters because each chunk gets a new decoder, and neither chunk holds the whole data line; one TextDecoder used with { stream: true } plus a buffer that keeps incomplete lines for the next chunk fixes both."', 'single_choice'::question_type, 'True. A new TextDecoder sees e1 bb at the end of chunk 1 as an incomplete character and a3 at the start of chunk 2 as an invalid byte, and replaces them with U+FFFD. Independently, splitting each chunk on blank lines assumes events never cross a chunk boundary, so chunk 1 yields the unfinished text data: {"delta":"G and JSON.parse fails. decoder.decode(chunk, { stream: true }) keeps the incomplete bytes until the next call, and a text buffer that only hands complete lines to the parser keeps the event together until its blank line arrives. The misconception is that a fetch chunk is a meaningful unit: the network can cut anywhere, even inside a character.', 2, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_nae_321') AND order_index = 2)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
SELECT q.id, o.option_text, o.is_correct
FROM q, (VALUES
        ('True', true),
        ('False', false)
    ) AS o(option_text, is_correct);

-- challenge chal_coding_nae_322 (mini_coding)
INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_coding_nae_322', (SELECT id FROM catalog.course WHERE public_id = 'nodejs-ai-engineering'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'nodejs-ai-engineering') AND order_index = 3 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-nae-3-2' AND is_deleted = false LIMIT 1), 'assemble-sse-stream', 'Assemble a recorded SSE stream: complete, truncated or error', 'The CodeDev AI tutor streams hints from the gateway to the browser as Server-Sent Events. The shipped client decoded and split every network chunk on its own and saved whatever it had when the reader finished: learners got replacement characters inside Vietnamese words, and a hint cut off by a proxy timeout was saved as finished. Write assembleStream(chunks: Uint8Array[]): { status, text, error }. The chunks are the bytes of one stream, cut at arbitrary places, including inside an event, between \r and \n and inside a multi-byte character. Rules: decode the bytes as UTF-8 with one decoder for the whole stream (a character can be split between chunks). A line ends with \n; remove one \r right before it. An empty line ends an event. A line starting with : is a comment and is ignored. Otherwise the field name is the text before the first colon and the value is the text after it, with one leading space removed (a line without a colon is a field with an empty value). event sets the event''s name; data adds a line to the event''s data; every other field (id, retry, ...) is ignored. When an event ends: if it has no data line, ignore it; its data is its data lines joined with \n; its name is the event value, or message when there was none. Then: an event named error ends the stream with status "error" and error = its data. A message whose data is exactly [DONE] ends the stream with status "complete". Any other message must be JSON for an object with a string delta: append delta to text; anything else (invalid JSON, not an object, no delta, delta not a string) ends the stream with status "error" and error "malformed event". Events with other names (ping, usage, ...) are ignored. Nothing after the end of the stream is read. If the bytes run out first, status is "truncated"; an event still waiting for its empty line is dropped, even if its data is [DONE]. text is every delta appended before the end, in every status; error is null unless status is "error". The runner rebuilds the chunks from each recording { stream, cuts } (cuts = byte offsets) and prints the list of results as JSON.', 'open', 'medium'::difficulty_question, 'mini_coding', 30, true, false)
ON CONFLICT (public_id) DO UPDATE SET
    course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, lesson_id = EXCLUDED.lesson_id, name = EXCLUDED.name,
    title = EXCLUDED.title, description = EXCLUDED.description, difficulty = EXCLUDED.difficulty, type = EXCLUDED.type,
    points = EXCLUDED.points, is_published = true, is_deleted = false, updated_at = now();
DELETE FROM challenge.challenge_hints WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_nae_322');
INSERT INTO challenge.challenge_hints (challenge_id, level, body)
VALUES ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_nae_322'), 1, 'What does your code still need to remember when one chunk ends and the next one has not arrived yet? List every piece of state that has to survive between two calls of the loop body.'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_nae_322'), 2, 'Look at four things: TextDecoder.decode(chunk, { stream: true }), which holds back an incomplete character; a string buffer where you only take text up to the next "\n" and leave the rest for later; the current event''s name and its list of data lines, which reset when an event ends; and the line after the loop, which is reached only when no done marker or error event was seen.'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_nae_322'), 3, 'A similar trace on different data. Stream: "event: ping\ndata: {}\n\ndata: {\"delta\":\n" + "data: \"Hi\"}\n\ndata: [DO" cut after byte 25. The buffer after chunk 1 holds a partial line, so nothing happens yet. Then: the ping event ends and is ignored; the next event has two data lines, joined as {"delta":\n"Hi"}, which is valid JSON, so text becomes "Hi"; then the bytes run out while "data: [DO" waits for its newline: status truncated, text "Hi", error null.');
