-- lesson 3.3: Token budgets & cost per user (Sanity lesson-nae-3-3)
UPDATE course.lesson SET title = 'Token budgets & cost per user', order_index = 3, module_id = (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'nodejs-ai-engineering') AND order_index = 3 AND is_deleted = false LIMIT 1), updated_at = now() WHERE id = (SELECT id FROM course.lesson WHERE content_source = 'lesson-nae-3-3' AND is_deleted = false LIMIT 1);
INSERT INTO course.lesson (module_id, title, content_type, content_source, order_index)
SELECT (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'nodejs-ai-engineering') AND order_index = 3 AND is_deleted = false LIMIT 1), 'Token budgets & cost per user', 'sanity', 'lesson-nae-3-3', 3
WHERE NOT EXISTS (SELECT 1 FROM course.lesson WHERE content_source = 'lesson-nae-3-3' AND is_deleted = false);

-- challenge chal_quiz_nae_331 (quiz)
INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_quiz_nae_331', (SELECT id FROM catalog.course WHERE public_id = 'nodejs-ai-engineering'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'nodejs-ai-engineering') AND order_index = 3 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-nae-3-3' AND is_deleted = false LIMIT 1), 'token-budget-evidence', 'Token budgets: what gets counted, and on which day?', 'Two pieces of evidence from the tutor''s budget incident: a usage record written twice by a retrying client, and the line of code that decides which day a request belongs to.', 'open', 'medium'::difficulty_question, 'quiz', 10, true, false)
ON CONFLICT (public_id) DO UPDATE SET
    course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, lesson_id = EXCLUDED.lesson_id, name = EXCLUDED.name,
    title = EXCLUDED.title, description = EXCLUDED.description, difficulty = EXCLUDED.difficulty, type = EXCLUDED.type,
    points = EXCLUDED.points, is_published = true, is_deleted = false, updated_at = now();
DELETE FROM challenge.challenge_hints WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_nae_331');
UPDATE challenge.challenges SET quiz_display_count = NULL WHERE id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_nae_331');
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_nae_331'), 'tutor_usage rows for a premium learner (daily limit 200,000 tokens):
 request_id | user_id | tokens | recorded_at
 req_88f1   | u_3307  |  95000 | 2026-10-21 08:00:20
 req_88f1   | u_3307  |  95000 | 2026-10-21 08:00:25

Gateway log:
POST /internal/usage timeout after 5000ms, retrying (1/2) request=req_88f1

Proposed change:
ALTER TABLE tutor_usage ADD PRIMARY KEY (user_id, request_id);
INSERT INTO tutor_usage (user_id, request_id, local_day, tokens) VALUES ($1, $2, $3, $4)
ON CONFLICT (user_id, request_id) DO NOTHING;

Statement: "With this change (after removing the duplicate row), the same retry would leave the learner''s usage for the day at 95,000 tokens instead of 190,000."', 'single_choice'::question_type, 'True. The first insert succeeded; only its response was slow, so the client''s retry sent the same record again. With a key on (user_id, request_id), the second insert conflicts with the first row and DO NOTHING skips it, so the request is counted once however many times the record is retried. This is what makes recording idempotent: the request id is the idempotency key, and the database enforces it, not the client. The misconception is that the fix is to stop retrying the record: then a record that really failed would be lost and the budget would undercount instead.', 1, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_nae_331') AND order_index = 1)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
SELECT q.id, o.option_text, o.is_correct
FROM q, (VALUES
        ('True', true),
        ('False', false)
    ) AS o(option_text, is_correct);
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_nae_331'), 'Learner profile: u_2291, plan free, utc_offset_minutes = 420 (Vietnam, UTC+7).
The budget code:
const day = new Date(request.at).toISOString().slice(0, 10);
const used = await sumUsage(request.userId, day);

A tutor request arrives with request.at = "2026-10-26T18:30:00Z".

Statement: "This request is counted on the learner''s budget for 27 October, the learner''s local date."', 'single_choice'::question_type, 'False. toISOString always formats the instant in UTC, so day is "2026-10-26". For the learner it is 01:30 on 27 October (18:30 + 7 hours), so the request lands on the previous day''s budget: a learner who used up 26 October stays blocked after their own midnight until 07:00 local time, which is exactly the support ticket. Shift the instant by the learner''s offset before taking the date (or format it with the learner''s IANA time zone). The misconception is that an ISO date string is "the" date, when it is the date in UTC.', 2, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_nae_331') AND order_index = 2)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
SELECT q.id, o.option_text, o.is_correct
FROM q, (VALUES
        ('True', false),
        ('False', true)
    ) AS o(option_text, is_correct);

-- challenge chal_coding_nae_332 (mini_coding)
INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_coding_nae_332', (SELECT id FROM catalog.course WHERE public_id = 'nodejs-ai-engineering'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'nodejs-ai-engineering') AND order_index = 3 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-nae-3-3' AND is_deleted = false LIMIT 1), 'daily-token-budget', 'A daily token budget per learner, with a fake clock', 'Every CodeDev AI tutor request goes through a daily token budget. The old budget only subtracted an estimate, used the UTC date and counted a retried record twice: a free account spent ten times its limit, a premium learner was blocked at noon and learners in Vietnam got their budget back at 07:00. Write runBudget(input) and return one outcome { ok, reason, remaining } per event, in order. Input: { dailyTokens: { free, premium }, users: [{ id, plan, utcOffsetMinutes }], events }. Each event has at (an ISO 8601 UTC instant: the fake clock, in time order) and userId, and is one of { type: "check", requestId, estimate } (before a model call), { type: "record", requestId, used } (after it, with the actual tokens) or { type: "remaining" }. Rules: the learner''s day is the calendar date of at shifted by utcOffsetMinutes (for +420, 2026-10-26T17:00:00Z is 2026-10-27 00:00 local), so the budget resets at the learner''s local midnight. used(day) is the sum of the tokens recorded for that learner with that local day (a record counts on the day of its own at). remaining = dailyTokens[plan] - used(day) of the event''s day, but never below 0. Unknown userId (any event): { ok: false, reason: "unknown user", remaining: null }. check: estimate not an integer greater than 0 gives reason "invalid estimate"; estimate greater than remaining gives "budget exceeded" (an estimate equal to remaining is allowed); otherwise ok. A check never changes the budget. record: used not an integer >= 0 gives reason "invalid usage"; a requestId already recorded for this learner (on any day, whatever the amount) gives "duplicate" and changes nothing; otherwise add used to that day and return ok. Rejected records are not remembered, so a later valid record with the same requestId still counts. The same requestId for two learners is two requests. remaining: ok. Every outcome except unknown user carries remaining for the event''s day after the event; reason is null when ok is true. The runner reads one input and prints the outcomes as JSON.', 'open', 'medium'::difficulty_question, 'mini_coding', 30, true, false)
ON CONFLICT (public_id) DO UPDATE SET
    course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, lesson_id = EXCLUDED.lesson_id, name = EXCLUDED.name,
    title = EXCLUDED.title, description = EXCLUDED.description, difficulty = EXCLUDED.difficulty, type = EXCLUDED.type,
    points = EXCLUDED.points, is_published = true, is_deleted = false, updated_at = now();
DELETE FROM challenge.challenge_hints WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_nae_332');
INSERT INTO challenge.challenge_hints (challenge_id, level, body)
VALUES ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_nae_332'), 1, 'Which piece of information decides which counter a check or a record looks at, and which piece decides whether a record was already applied? They are different keys.'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_nae_332'), 2, 'Look at three places: a helper that turns (at, utcOffsetMinutes) into a local date string by adding the offset in milliseconds to Date.parse(at) and reading the UTC date with toISOString().slice(0, 10); a Map from "user|day" to tokens used; and a Set of "user|requestId" for records already applied. Compute remaining with Math.max(0, ...) in one place and use it for every outcome.'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_nae_332'), 3, 'A similar trace on different numbers: a plan with 1,000 tokens a day and a learner at utcOffsetMinutes -60. check at 2026-03-01T00:30:00Z, estimate 800: the local date is still 2026-02-28, remaining 1000, ok. record r1 used 1,200 at 00:31Z: that day''s usage is 1,200, remaining 0. The same record r1 again: duplicate, remaining 0. check at 01:00:00Z, estimate 1,000: local time is 00:00 on 2026-03-01, a new day, remaining 1000, ok because 1,000 is not greater than 1,000.');
