       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_nae_332'), 'The budget resets at the learner''s local midnight (UTC+7), not at midnight UTC', '{"dailyTokens":{"free":20000,"premium":200000},"users":[{"id":"u_2291","plan":"free","utcOffsetMinutes":420}],"events":[{"type":"check","at":"2026-10-25T20:00:00Z","userId":"u_2291","requestId":"req_10","estimate":15000},{"type":"record","at":"2026-10-25T20:00:05Z","userId":"u_2291","requestId":"req_10","used":15000},{"type":"check","at":"2026-10-25T23:30:00Z","userId":"u_2291","requestId":"req_11","estimate":6000},{"type":"remaining","at":"2026-10-26T16:59:59Z","userId":"u_2291"},{"type":"check","at":"2026-10-26T17:00:00Z","userId":"u_2291","requestId":"req_12","estimate":6000},{"type":"record","at":"2026-10-26T17:00:09Z","userId":"u_2291","requestId":"req_12","used":6000}]}', '[{"ok":true,"reason":null,"remaining":20000},{"ok":true,"reason":null,"remaining":5000},{"ok":false,"reason":"budget exceeded","remaining":5000},{"ok":true,"reason":null,"remaining":5000},{"ok":true,"reason":null,"remaining":20000},{"ok":true,"reason":null,"remaining":14000}]', 3, true, false, 2),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_nae_332'), 'Recording is idempotent per request id; the same id for another learner is another request', '{"dailyTokens":{"free":20000,"premium":200000},"users":[{"id":"u_3307","plan":"premium","utcOffsetMinutes":0},{"id":"u_3308","plan":"free","utcOffsetMinutes":0}],"events":[{"type":"check","at":"2026-10-26T08:00:00Z","userId":"u_3307","requestId":"req_a","estimate":90000},{"type":"record","at":"2026-10-26T08:00:20Z","userId":"u_3307","requestId":"req_a","used":95000},{"type":"record","at":"2026-10-26T08:00:25Z","userId":"u_3307","requestId":"req_a","used":95000},{"type":"record","at":"2026-10-26T08:00:40Z","userId":"u_3307","requestId":"req_a","used":1000},{"type":"check","at":"2026-10-26T12:10:00Z","userId":"u_3307","requestId":"req_b","estimate":100000},{"type":"record","at":"2026-10-26T12:10:30Z","userId":"u_3308","requestId":"req_a","used":5000},{"type":"remaining","at":"2026-10-26T12:11:00Z","userId":"u_3308"},{"type":"record","at":"2026-10-27T08:00:00Z","userId":"u_3307","requestId":"req_a","used":5000},{"type":"remaining","at":"2026-10-27T08:00:01Z","userId":"u_3307"}]}', '[{"ok":true,"reason":null,"remaining":200000},{"ok":true,"reason":null,"remaining":105000},{"ok":false,"reason":"duplicate","remaining":105000},{"ok":false,"reason":"duplicate","remaining":105000},{"ok":true,"reason":null,"remaining":105000},{"ok":true,"reason":null,"remaining":15000},{"ok":true,"reason":null,"remaining":15000},{"ok":false,"reason":"duplicate","remaining":200000},{"ok":true,"reason":null,"remaining":200000}]', 3, false, true, 3),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_nae_332'), 'Actual usage above the estimate: remaining stops at 0, later checks are rejected', '{"dailyTokens":{"free":20000,"premium":200000},"users":[{"id":"u_5512","plan":"free","utcOffsetMinutes":60}],"events":[{"type":"check","at":"2026-10-26T07:00:00Z","userId":"u_5512","requestId":"req_1","estimate":18000},{"type":"record","at":"2026-10-26T07:00:30Z","userId":"u_5512","requestId":"req_1","used":26500},{"type":"remaining","at":"2026-10-26T07:01:00Z","userId":"u_5512"},{"type":"check","at":"2026-10-26T07:02:00Z","userId":"u_5512","requestId":"req_2","estimate":1},{"type":"record","at":"2026-10-26T07:03:00Z","userId":"u_5512","requestId":"req_2","used":0},{"type":"remaining","at":"2026-10-26T22:59:59Z","userId":"u_5512"},{"type":"check","at":"2026-10-26T23:00:00Z","userId":"u_5512","requestId":"req_3","estimate":20000},{"type":"record","at":"2026-10-26T23:00:10Z","userId":"u_5512","requestId":"req_3","used":20000},{"type":"check","at":"2026-10-26T23:01:00Z","userId":"u_5512","requestId":"req_4","estimate":1}]}', '[{"ok":true,"reason":null,"remaining":20000},{"ok":true,"reason":null,"remaining":0},{"ok":true,"reason":null,"remaining":0},{"ok":false,"reason":"budget exceeded","remaining":0},{"ok":true,"reason":null,"remaining":0},{"ok":true,"reason":null,"remaining":0},{"ok":true,"reason":null,"remaining":20000},{"ok":true,"reason":null,"remaining":0},{"ok":false,"reason":"budget exceeded","remaining":0}]', 3, false, true, 4),
