        ('True', false),
        ('False', true)
    ) AS o(option_text, is_correct);

-- challenge chal_coding_nae_412 (fix_bug)
INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_coding_nae_412', (SELECT id FROM catalog.course WHERE public_id = 'nodejs-ai-engineering'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'nodejs-ai-engineering') AND order_index = 4 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-nae-4-1' AND is_deleted = false LIMIT 1), 'spot-the-ai-mistake-hint-leak-filter', 'Spot the AI Mistake: a hint that leaks the solution', 'CodeDev''s AI hint service sends the learner''s code, the failing test and the challenge''s reference solution to a model and shows the generated hint on the lesson page. The request sent to an AI coding assistant was: "Add an output filter to the hint service. A generated hint must never contain the reference solution of the challenge: if it does, return FALLBACK_HINT instead. Normal hints, including ones that mention a function name, must go through unchanged." The assistant wrote filterHint, the reviewer pasted the reference into a hint, saw it blocked, and the change was merged. Learners now report hints that contain the whole solution with renamed variables, with different spacing, with comments added, or split into two code blocks.

Fix filterHint(hint, reference) so that it follows the team''s policy (the constants NGRAM = 8, MAX_SHARED = 0.3 and KEYWORDS are in the starter):
1. Remove comments: every /* ... */ (up to the first */, or to the end of the text when it is not closed), then every // up to the end of its line.
2. Split into tokens: a word is a run of letters, digits, _ and $; every other character that is not whitespace is a token on its own (=== is three tokens). Whitespace only separates tokens.
3. A word that starts with a letter, _ or $ and is not in KEYWORDS becomes the token ID. Keywords and words that start with a digit stay as they are.
4. An n-gram is a run of NGRAM consecutive tokens. share = (distinct n-grams of the reference that also appear in the hint) / (distinct n-grams of the reference).
5. Return FALLBACK_HINT when share >= MAX_SHARED, otherwise return the hint unchanged.
A hint that is empty or only whitespace gets FALLBACK_HINT. A reference with fewer than NGRAM tokens (no reference configured) blocks nothing.

Input (stdin, JSON): { "reference": "<reference solution>", "hints": ["<hint>", ...] }. Output: one line per hint, "hint <n>: allowed", "hint <n>: fallback" or "hint <n>: changed" (printed by the test runner). Up to 200 hints of up to 2,000 characters each. Do not change the policy constants or the test runner. The public tests pass on the assistant''s code; the hidden tests use renamed, reformatted, commented and split copies, and check that ordinary hints that name the function or quote one line still go through.', 'open', 'medium'::difficulty_question, 'fix_bug', 30, true, false)
