INSERT INTO challenge.challenge_hints (challenge_id, level, body)
VALUES ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_nae_412'), 1, 'The assistant''s check asks "does this exact text appear in the hint?". Which edits keep the solution just as useful to a learner but change its text?'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_nae_412'), 2, 'Look at what the two texts are compared as. flatten() only collapses whitespace: the policy wants comments removed first, a list of tokens instead of characters, every non-keyword word turned into ID, and then a count of shared runs of NGRAM tokens, not a substring test.'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_nae_412'), 3, 'A similar case with NGRAM = 3. Reference "x = y + 1;" gives the tokens ID = ID + 1 ; and four 3-grams ("ID = ID", "= ID +", "ID + 1", "+ 1 ;"). The hint "try a=b+1; // add one" loses its comment and gives the same tokens: 4 of 4 shared, share 1.0, fallback. The hint "set x = 0 first" gives ID ID = 0 ID: none of the four 3-grams, share 0, allowed.');
