INSERT INTO challenge.challenge_test_cases (challenge_id, name, input_data, expected_output, score, is_sample, is_hidden, sort_order)
VALUES ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_nae_412'), 'A hint that pastes the reference with new indentation is blocked', '{"reference":"function topWords(text: string, k: number): string[] {\n    const counts = new Map<string, number>();\n    for (const word of text.toLowerCase().split(/\\s+/)) {\n        if (word === \"\") continue;\n        counts.set(word, (counts.get(word) ?? 0) + 1);\n    }\n    return [...counts.entries()]\n        .sort((a, b) => b[1] - a[1] || a[0].localeCompare(b[0]))\n        .slice(0, k)\n        .map(([word]) => word);\n}","hints":["Here is one way to write it:\n\n```ts\nfunction topWords(text: string, k: number): string[] {\n  const counts = new Map<string, number>();\n  for (const word of text.toLowerCase().split(/\\s+/)) {\n    if (word === \"\") continue;\n    counts.set(word, (counts.get(word) ?? 0) + 1);\n  }\n  return [...counts.entries()]\n    .sort((a, b) => b[1] - a[1] || a[0].localeCompare(b[0]))\n    .slice(0, k)\n    .map(([word]) => word);\n}\n```\n\nCompare it with your version.","Split the text into words first. What should happen to \"Hello\" and \"hello\": one word or two?"]}', '"hint 1: fallback\nhint 2: allowed"', 3, true, false, 1),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_nae_412'), 'Normal hints go through unchanged', '{"reference":"function topWords(text: string, k: number): string[] {\n    const counts = new Map<string, number>();\n    for (const word of text.toLowerCase().split(/\\s+/)) {\n        if (word === \"\") continue;\n        counts.set(word, (counts.get(word) ?? 0) + 1);\n    }\n    return [...counts.entries()]\n        .sort((a, b) => b[1] - a[1] || a[0].localeCompare(b[0]))\n        .slice(0, k)\n        .map(([word]) => word);\n}","hints":["Split the text into words first. What should happen to \"Hello\" and \"hello\": one word or two?","Count with a Map from word to number. When two words have the same count, which one comes first in the expected output?","Check the empty input: what does your function return when the text is only spaces?"]}', '"hint 1: allowed\nhint 2: allowed\nhint 3: allowed"', 3, true, false, 2),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_nae_412'), 'A copy with renamed variables and no spaces is blocked', '{"reference":"function topWords(text: string, k: number): string[] {\n    const counts = new Map<string, number>();\n    for (const word of text.toLowerCase().split(/\\s+/)) {\n        if (word === \"\") continue;\n        counts.set(word, (counts.get(word) ?? 0) + 1);\n    }\n    return [...counts.entries()]\n        .sort((a, b) => b[1] - a[1] || a[0].localeCompare(b[0]))\n        .slice(0, k)\n        .map(([word]) => word);\n}","hints":["Almost there! Your function should look like this:\n\nfunction best(input:string,limit:number):string[]{\n  const freq=new Map<string,number>();\n  for(const w of input.toLowerCase().split(/\\s+/)){\n    if(w===\"\")continue;\n    freq.set(w,(freq.get(w)??0)+1);\n  }\n  return [...freq.entries()].sort((x,y)=>y[1]-x[1]||x[0].localeCompare(y[0])).slice(0,limit).map(([w])=>w);\n}\n\nRun the tests again.","Count with a Map from word to number. When two words have the same count, which one comes first in the expected output?"]}', '"hint 1: fallback\nhint 2: allowed"', 3, false, true, 3),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_nae_412'), 'A copy with comments added inside the lines is blocked', '{"reference":"function topWords(text: string, k: number): string[] {\n    const counts = new Map<string, number>();\n    for (const word of text.toLowerCase().split(/\\s+/)) {\n        if (word === \"\") continue;\n        counts.set(word, (counts.get(word) ?? 0) + 1);\n    }\n    return [...counts.entries()]\n        .sort((a, b) => b[1] - a[1] || a[0].localeCompare(b[0]))\n        .slice(0, k)\n        .map(([word]) => word);\n}","hints":["Check the empty input: what does your function return when the text is only spaces?","Let me explain it line by line:\n```ts\nfunction topWords(text: string /* the input */, k: number /* how many */): string[] {\n    // 1. count every word\n    const counts /* word -> count */ = new Map<string, number>();\n    for (const word /* each word */ of text.toLowerCase() /* ignore case */ .split(/\\s+/) /* on spaces */) {\n        if (word === \"\" /* leading spaces */) continue; // skip it\n        counts.set(word /* key */, (counts.get(word) /* old count */ ?? 0) + 1 /* one more */);\n    }\n    // 2. sort by count, then alphabetically\n    return [...counts.entries()] /* [word, count] pairs */\n        .sort((a, b) /* compare two pairs */ => b[1] - a[1] /* higher count first */ || a[0].localeCompare(b[0]) /* then A to Z */)\n        .slice(0, k) /* only the first k */\n        .map(([word]) /* keep the word */ => word);\n}\n```"]}', '"hint 1: allowed\nhint 2: fallback"', 3, false, true, 4),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_nae_412'), 'A copy split into two code blocks with text in between is blocked', '{"reference":"function topWords(text: string, k: number): string[] {\n    const counts = new Map<string, number>();\n    for (const word of text.toLowerCase().split(/\\s+/)) {\n        if (word === \"\") continue;\n        counts.set(word, (counts.get(word) ?? 0) + 1);\n    }\n    return [...counts.entries()]\n        .sort((a, b) => b[1] - a[1] || a[0].localeCompare(b[0]))\n        .slice(0, k)\n        .map(([word]) => word);\n}","hints":["Start by counting:\n```ts\nconst counts = new Map<string, number>();\nfor (const word of text.toLowerCase().split(/\\s+/)) {\n  if (word === \"\") continue;\n  counts.set(word, (counts.get(word) ?? 0) + 1);\n}\n```\nThen turn the map into the answer:\n```ts\nreturn [...counts.entries()]\n  .sort((a, b) => b[1] - a[1] || a[0].localeCompare(b[0]))\n  .slice(0, k)\n  .map(([word]) => word);\n```","Split the text into words first. What should happen to \"Hello\" and \"hello\": one word or two?"]}', '"hint 1: fallback\nhint 2: allowed"', 3, false, true, 5),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_nae_412'), 'Hints that name the function or quote one line go through', '{"reference":"function topWords(text: string, k: number): string[] {\n    const counts = new Map<string, number>();\n    for (const word of text.toLowerCase().split(/\\s+/)) {\n        if (word === \"\") continue;\n        counts.set(word, (counts.get(word) ?? 0) + 1);\n    }\n    return [...counts.entries()]\n        .sort((a, b) => b[1] - a[1] || a[0].localeCompare(b[0]))\n        .slice(0, k)\n        .map(([word]) => word);\n}","hints":["Your `topWords(text, k)` returns the words in the order they first appear. Which line decides the order of the result?","Loop over the words with `for (const word of text.toLowerCase().split(/\\s+/))` and look at what `split` gives you when the text starts with a space.","Counting is fine: `counts.set(word, (counts.get(word) ?? 0) + 1);` is enough. The missing part is the order of words with the same count."]}', '"hint 1: allowed\nhint 2: allowed\nhint 3: allowed"', 3, false, true, 6),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_nae_412'), 'Empty hint gets the fallback; no reference configured blocks nothing', '{"reference":"","hints":["","  \n\t ","Count with a Map from word to number. When two words have the same count, which one comes first in the expected output?","Try `for (const w of words) { counts.set(w, 1); }` on a short text first."]}', '"hint 1: fallback\nhint 2: fallback\nhint 3: allowed\nhint 4: allowed"', 2, false, true, 7),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_nae_412'), '120 hints for a longer reference: every leak blocked, every normal hint allowed', '{"reference":"type Entry = { userId: string; exp: number; finishedAt: number };\n\nfunction rankLeaderboard(entries: Entry[], limit: number): string[] {\n    const best = new Map<string, Entry>();\n    for (const entry of entries) {\n        const current = best.get(entry.userId);\n        if (!current || entry.exp > current.exp || (entry.exp === current.exp && entry.finishedAt < current.finishedAt)) {\n            best.set(entry.userId, entry);\n        }\n    }\n    const rows = [...best.values()].sort((a, b) => b.exp - a.exp || a.finishedAt - b.finishedAt);\n    const result: string[] = [];\n    for (let i = 0; i < rows.length && i < limit; i++) {\n        result.push(`${i + 1}. ${rows[i].userId} ${rows[i].exp}`);\n    }\n    return result;\n}","hints":["One thing is missing. Which entry should win when the same learner appears twice with the same EXP? A Map keyed by userId keeps one entry per learner.","You are close. Does your sort put the highest EXP first, and what breaks a tie? The loop condition `for (let i = 0; i < rows.length && i < l...` stops at the limit; check the other half of it.","Look again at the task. Does your sort put the highest EXP first, and what breaks a tie? The loop condition `for (let i = 0; i < rows.length && i < l...` stops at the limit; check the other half of it.","Here is the idea in code:\n\ntype Row = { userId: string; exp: number; finishedAt: number }; function topLearners(list: Row[], n: number): string[] { const byUser = new Map<string, Row>(); for (const e of list) { const prev = byUser.get(e.userId); if (!prev || e.exp > prev.exp || (e.exp === prev.exp && e.finishedAt < prev.finishedAt)) { byUser.set(e.userId, e); } } const sorted = [...byUser.values()].sort((p, q) => q.exp - p.exp || p.finishedAt - q.finishedAt); const lines: string[] = []; for (let j = 0;