Statement: "Stopping here instead of calling the real model is the intended behavior: a new prompt version needs fixtures recorded on purpose, and their content reviewed in the pull request, before CI can replay them."', 'single_choice'::question_type, 'True. The replay gateway looks fixtures up by prompt version, model, parameters and input, and the v5 recordings do not describe what v6 answers. Calling the real model from CI would make the build slow, flaky and paid, and it would silently test something nobody looked at. Failing with a clear message keeps the rule: recording is a deliberate step by a person with a key, the new fixtures appear in the diff of the pull request, and a reviewer reads what v6 actually says before the tests start relying on it. Reusing the v5 fixtures for v6 would make the tests pass while testing the old prompt. The misconception is that a test which cannot find its fixture should fall back to the real service.', 2, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_nae_431') AND order_index = 2)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
SELECT q.id, o.option_text, o.is_correct
FROM q, (VALUES
        ('True', true),
        ('False', false)
    ) AS o(option_text, is_correct);

-- learners enrolled before these lessons existed
INSERT INTO learning.history (user_id, course_id, module_id, lesson_id)
SELECT r.user_id, r.course_id, m.id, l.id
FROM learning.register r
JOIN course.module m ON m.course_id = r.course_id AND m.is_deleted = false
JOIN course.lesson l ON l.module_id = m.id AND l.is_deleted = false
WHERE r.course_id = (SELECT id FROM catalog.course WHERE public_id = 'nodejs-ai-engineering') AND r.is_deleted = false
ON CONFLICT DO NOTHING;
WITH ordered AS (
    SELECT h.user_id, h.lesson_id, h.status,
           row_number() OVER (PARTITION BY h.user_id ORDER BY m.order_index, l.order_index) AS rn
    FROM learning.history h
    JOIN course.lesson l ON l.id = h.lesson_id AND l.is_deleted = false
    JOIN course.module m ON m.id = l.module_id AND m.is_deleted = false
    WHERE h.course_id = (SELECT id FROM catalog.course WHERE public_id = 'nodejs-ai-engineering')
),
next_lesson AS (
    SELECT DISTINCT ON (o.user_id) o.user_id, o.lesson_id
    FROM ordered o
    WHERE o.status = 'enrolled'
      AND NOT EXISTS (SELECT 1 FROM ordered p WHERE p.user_id = o.user_id AND p.rn < o.rn AND p.status <> 'completed')
    ORDER BY o.user_id, o.rn
)
UPDATE learning.history h
SET status = 'in_progress', updated_at = now()
FROM next_lesson n
JOIN learning.register r ON r.user_id = n.user_id AND r.course_id = (SELECT id FROM catalog.course WHERE public_id = 'nodejs-ai-engineering') AND r.is_deleted = false AND r.status <> 'enrolled'
WHERE h.user_id = n.user_id AND h.course_id = (SELECT id FROM catalog.course WHERE public_id = 'nodejs-ai-engineering') AND h.lesson_id = n.lesson_id;
UPDATE learning.register r
SET status = 'in_progress'
WHERE r.course_id = (SELECT id FROM catalog.course WHERE public_id = 'nodejs-ai-engineering') AND r.status = 'completed'
  AND EXISTS (SELECT 1 FROM learning.history h WHERE h.user_id = r.user_id AND h.course_id = (SELECT id FROM catalog.course WHERE public_id = 'nodejs-ai-engineering') AND h.status <> 'completed');

COMMIT;
